fn unhex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

#[test]
fn matches_reference() {
    for &(n, len, key, person, salt, expect) in CASES {
        let data: Vec<u8> = (0..n).map(|i| ((i * 7 + 3) & 255) as u8).collect();
        let mut p = Params::new();
        p.hash_length(len).key(&unhex(key)).personal(&unhex(person)).salt(&unhex(salt));
        assert_eq!(p.hash(&data).as_bytes(), &unhex(expect)[..], "n {n} len {len}");
        // Same through a state fed in odd pieces.
        let mut st = p.to_state();
        for chunk in data.chunks(37) {
            st.update(chunk);
        }
        assert_eq!(st.finalize().as_bytes(), &unhex(expect)[..], "chunked n {n}");
    }
}
